insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_manufacturing','manufacturing','noun','the business of making goods in large numbers, usually in factories using machines','[{"senseId":"manufacturing_1","meaning":"the business of making goods in large numbers, usually in factories using machines","acceptedParaphrases":["factory production of goods","making goods in large quantities"],"masteryContexts":[{"contextId":"u8_21_manufacturing_meaning","text":"In the north of the country, manufacturing is still important, and many people work in car factories.","meaning":"making goods in factories","wrongMeanings":["growing food on farms","selling goods in shops","teaching skills in colleges"]},{"contextId":"u8_21_manufacturing_paraphrase","text":"The company moved its manufacturing to a larger site so that it could produce more phones.","meaning":"the making of its products","wrongMeanings":["the selling of its products","the advertising of its products","the repairing of its products"]}],"situationDistractors":["A potter made one bowl by hand for a friend.","A shop assistant arranged sweaters on a display table.","A lorry driver delivered goods to a supermarket.","A designer sketched an idea for a new chair.","A salesperson phoned customers to offer a discount.","A farmer harvested potatoes in a field."],"gapDistractors":[{"contextId":"u8_21_manufacturing_gap_1","answer":"manufacturing","wrong":["packaging","wellbeing","humanity"]},{"contextId":"u8_21_manufacturing_gap_2","answer":"manufacturing","wrong":["wellbeing","humanity","minority"]},{"contextId":"u8_21_manufacturing_gap_3","answer":"manufacturing","wrong":["wellbeing","publicity","humanity"]}],"spellingErrors":["manufactoring","manifacturing","manufacuring","manufaturing","manufactuering","manufacturring"],"wordFamilyForms":[{"form":"manufacturing","partOfSpeech":"noun","example":"Jobs in manufacturing often involve working with heavy machines.","pedagogicallyUseful":true},{"form":"manufacture","partOfSpeech":"verb","example":"The factory can manufacture ten thousand bottles a day.","pedagogicallyUseful":true,"altExample":"The company plans to manufacture electric bikes in Spain."},{"form":"manufacturer","partOfSpeech":"noun","example":"The manufacturer offered to replace the faulty washing machine.","pedagogicallyUseful":true,"altExample":"Contact the manufacturer if the product breaks within a year."}],"masteryPassages":[{"passageId":"u8_21_manufacturing_passage_1","contextId":"u8_21_manufacturing_gap_1","text":"The old factories in the city now stand empty. Fifty years ago, ____ employed half the town, but most products are now made abroad.","answer":"manufacturing"},{"passageId":"u8_21_manufacturing_passage_2","contextId":"u8_21_manufacturing_gap_2","text":"The phone was designed in California. Its ____ takes place in huge factories in Asia, where thousands of workers put the parts together.","answer":"manufacturing"}],"contextDependentParaphrases":[],"wrongParaphrases":["shop sales of goods","farm growing of food","sea transport of goods"],"misleadingDistractors":["selling goods to customers in shops","designing a single item by hand","moving goods from one country to another"],"teacherNote":"Noun: making goods in large numbers, usually in factories (the manufacturing industry, car manufacturing). Boundary: manufacturing is mass production; a craftsperson making one item by hand is not manufacturing. The verb manufacture and the noun manufacturer are taught in the Word Family pathway."}]'::jsonb,'["manufacture","manufacturer"]'::jsonb,'["the manufacturing industry","car manufacturing","manufacturing costs"]'::jsonb,'live'),
('vocab_minority','minority','noun','the smaller part of a group, less than half','[{"senseId":"minority_1","meaning":"the smaller part of a group, less than half","acceptedParaphrases":["less than half","a smaller number of a group"],"masteryContexts":[{"contextId":"u8_22_minority_meaning","text":"A minority of customers complained about the new packaging, but most were happy with it.","meaning":"fewer than half of a group","wrongMeanings":["all of a group","most of a group","none of a group"]},{"contextId":"u8_22_minority_paraphrase","text":"In this company, women are still a minority of the engineers, though the number is growing.","meaning":"a smaller part of a group","wrongMeanings":["the larger part of a group","the leaders of a group","the newest members of a group"]}],"situationDistractors":["Ninety per cent of the workers voted for the new plan.","Every employee attended the training day.","Most of the customers chose the cheaper option.","All the staff received a bonus at the end of the year.","Nearly everyone in the office drinks coffee.","The whole team agreed to start earlier."],"gapDistractors":[{"contextId":"u8_22_minority_gap_1","answer":"minority","wrong":["humanity","publicity","availability"]},{"contextId":"u8_22_minority_gap_2","answer":"minority","wrong":["humanity","publicity","response"]},{"contextId":"u8_22_minority_gap_3","answer":"minority","wrong":["humanity","publicity","technology"]}],"spellingErrors":["minorty","minorrity","minoraty","mynority","minoritty","minorety"],"masteryPassages":[{"passageId":"u8_22_minority_passage_1","contextId":"u8_22_minority_gap_1","text":"Most people in the survey were happy with their jobs. Only a small ____, about one in ten, said they wanted to change careers.","answer":"minority"},{"passageId":"u8_22_minority_passage_2","contextId":"u8_22_minority_gap_2","text":"In the 1960s, very few women worked as engineers. They were a tiny ____ of the workforce, and many faced unfair treatment.","answer":"minority"}],"contextDependentParaphrases":[],"wrongParaphrases":["more than half","exactly half","almost all"],"misleadingDistractors":["more than half of a group","every single member of a group","the leader of a group"],"teacherNote":"Noun: the smaller part of a group, less than half (a minority of students, only a small minority). Boundary: minority can also mean a group of people who differ in race or religion from most of a population; Unit 8 teaches the \"less than half\" sense. Its opposite, majority, is a different word, so no family is taught."}]'::jsonb,'[]'::jsonb,'["a small minority","a minority of people","only a minority"]'::jsonb,'live'),
('vocab_packaging','packaging','noun','the boxes, bottles, paper or plastic in which goods are wrapped for sale','[{"senseId":"packaging_1","meaning":"the boxes, bottles, paper or plastic in which goods are wrapped for sale","acceptedParaphrases":["materials used to wrap products","boxes and wrappers for goods"],"masteryContexts":[{"contextId":"u8_23_packaging_meaning","text":"Customers complained that the toy came in too much plastic packaging.","meaning":"the material that a product is wrapped in","wrongMeanings":["the instructions that come with a product","the shop where a product is sold","the factory where a product is made"]},{"contextId":"u8_23_packaging_paraphrase","text":"The designer chose bright packaging so that the new juice would stand out on the shelf.","meaning":"the box or bottle a product is sold in","wrongMeanings":["the taste of the drink inside","the price of the drink","the advert for the drink"]}],"situationDistractors":["A chef tasted the soup before serving it.","A salesman explained the price of a new car.","A scientist tested a new medicine in a laboratory.","A customer complained that her coffee was cold.","A manager counted the money in the till.","A driver checked the tyres on his van."],"gapDistractors":[{"contextId":"u8_23_packaging_gap_1","answer":"packaging","wrong":["manufacturing","wellbeing","humanity"]},{"contextId":"u8_23_packaging_gap_2","answer":"packaging","wrong":["wellbeing","humanity","minority"]},{"contextId":"u8_23_packaging_gap_3","answer":"packaging","wrong":["wellbeing","publicity","humanity"]}],"spellingErrors":["packeging","packageing","pakaging","packging","packadging","packagin"],"wordFamilyForms":[{"form":"packaging","partOfSpeech":"noun","example":"The supermarket wants to cut the amount of plastic packaging it uses.","pedagogicallyUseful":true},{"form":"pack","partOfSpeech":"verb","example":"Workers pack the biscuits into boxes at the end of the line.","pedagogicallyUseful":true,"altExample":"The machine can pack two hundred boxes an hour."},{"form":"package","partOfSpeech":"noun","example":"A package arrived at the office this morning.","pedagogicallyUseful":true,"altExample":"Please sign here to show that you have received the package."}],"masteryPassages":[{"passageId":"u8_23_packaging_passage_1","contextId":"u8_23_packaging_gap_1","text":"The new phone came in a large box, with plastic bags, foam and cardboard inside. All that ____ went straight into the bin.","answer":"packaging"},{"passageId":"u8_23_packaging_passage_2","contextId":"u8_23_packaging_gap_2","text":"Many shoppers now avoid products wrapped in plastic. As a result, the company redesigned its ____ and now uses only paper and card.","answer":"packaging"}],"contextDependentParaphrases":[],"wrongParaphrases":["money used to advertise products","machines used to make products","people paid to sell products"],"misleadingDistractors":["the goods that are inside a box","the price label on a product","the advertising for a new product"],"teacherNote":"Noun (uncountable): the boxes, bottles, paper or plastic that products are sold in (plastic packaging, recyclable packaging). Boundary: packaging is the material around a product; the product itself and its label are different. The verb pack and the noun package are taught in the Word Family pathway."}]'::jsonb,'["pack","package"]'::jsonb,'["plastic packaging","recyclable packaging","food packaging"]'::jsonb,'live'),
('vocab_presented','presented','verb','formally showed or explained something to a group of people','[{"senseId":"presented_1","meaning":"formally showed or explained something to a group of people","acceptedParaphrases":["showed formally","explained to an audience"],"masteryContexts":[{"contextId":"u8_24_presented_meaning","text":"The scientist presented her results at a conference in Tokyo.","meaning":"explained formally to an audience","wrongMeanings":["hid carefully from other people","checked again in a laboratory","sold for money to a company"]},{"contextId":"u8_24_presented_paraphrase","text":"Each team presented its idea for a new product to a panel of judges.","meaning":"showed and explained to a group","wrongMeanings":["kept secret from a group","threw away without showing","tested quietly at home"]}],"situationDistractors":["A manager read an email silently at her desk.","A designer kept her drawings locked in a drawer.","A worker wrote notes in his private diary.","A cleaner tidied the meeting room after everyone left.","An engineer fixed a printer on her own.","A trainee ate lunch alone in the park."],"gapDistractors":[{"contextId":"u8_24_presented_gap_1","answer":"presented","wrong":["concerned","qualified","curved"]},{"contextId":"u8_24_presented_gap_2","answer":"presented","wrong":["qualified","concerned","curved"]},{"contextId":"u8_24_presented_gap_3","answer":"presented","wrong":["concerned","curved","established"]}],"spellingErrors":["presentted","prisented","presentid","presended","pressented","presentd"],"wordFamilyForms":[{"form":"presented","partOfSpeech":"verb","example":"The team presented their findings at the end of the course.","pedagogicallyUseful":true},{"form":"presentation","partOfSpeech":"noun","example":"Maria gave a short presentation about the new product.","pedagogicallyUseful":true,"altExample":"The presentation lasted twenty minutes and included a short video."},{"form":"presenter","partOfSpeech":"noun","example":"The presenter thanked the audience and answered questions.","pedagogicallyUseful":true,"altExample":"The television presenter interviewed the young inventor."}],"masteryPassages":[{"passageId":"u8_24_presented_passage_1","contextId":"u8_24_presented_gap_1","text":"Before the meeting, Kim prepared twenty slides and practised her talk. Then she stood up and ____ her ideas to the managers, who asked many questions.","answer":"presented"},{"passageId":"u8_24_presented_passage_2","contextId":"u8_24_presented_gap_2","text":"At the science fair, every student stood beside a poster. One by one, they ____ their experiments to the judges and answered their questions.","answer":"presented"}],"contextDependentParaphrases":[],"wrongParaphrases":["hid carefully","sold cheaply","lost suddenly"],"misleadingDistractors":["kept secret from other people","threw away without using","copied from another person"],"teacherNote":"Verb (past tense or past participle): formally showed or explained something to a group (presented a plan, presented the results to the board). Boundary: presented can also mean formally gave (presented an award to); Unit 8 focuses on showing and explaining at work. The nouns presentation and presenter are taught in the Word Family pathway."}]'::jsonb,'["presentation","presenter"]'::jsonb,'["presented a plan","presented the results","presented to the board"]'::jsonb,'live'),
('vocab_publicity','publicity','noun','attention from newspapers, television and the internet, or the work of getting this attention','[{"senseId":"publicity_1","meaning":"attention from newspapers, television and the internet, or the work of getting this attention","acceptedParaphrases":["public attention","media attention"],"masteryContexts":[{"contextId":"u8_25_publicity_meaning","text":"The film star’s visit gave the small bookshop a lot of publicity.","meaning":"attention from newspapers and television","wrongMeanings":["money from banks and investors","advice from experts and teachers","complaints from customers and staff"]},{"contextId":"u8_25_publicity_paraphrase","text":"The company hired a team to handle publicity for the launch of its new phone.","meaning":"activities to get noticed by many people","wrongMeanings":["activities to repair broken products","activities to train new staff","activities to reduce the costs"]}],"situationDistractors":["A shop owner quietly counted her stock after closing.","A worker kept his promotion a secret from his friends.","A company held a private meeting with no reporters.","An engineer repaired a machine in an empty factory.","A clerk filed old invoices in a cupboard.","A scientist checked her results alone at night."],"gapDistractors":[{"contextId":"u8_25_publicity_gap_1","answer":"publicity","wrong":["humanity","minority","availability"]},{"contextId":"u8_25_publicity_gap_2","answer":"publicity","wrong":["humanity","minority","architecture"]},{"contextId":"u8_25_publicity_gap_3","answer":"publicity","wrong":["humanity","minority","architecture"]}],"spellingErrors":["publisity","publicty","publicitty","pubicity","publicaty","publiscity"],"wordFamilyForms":[{"form":"publicity","partOfSpeech":"noun","example":"The new museum attracted a lot of publicity in its first week.","pedagogicallyUseful":true},{"form":"public","partOfSpeech":"adjective","example":"The council held a public meeting about the new factory.","pedagogicallyUseful":true,"altExample":"The library is a public building, so anyone can use it."},{"form":"publicise","partOfSpeech":"verb","example":"The school used posters to publicise the charity concert.","pedagogicallyUseful":true,"altExample":"Companies use social media to publicise new products."}],"masteryPassages":[{"passageId":"u8_25_publicity_passage_1","contextId":"u8_25_publicity_gap_1","text":"Nobody had heard of the small café until a famous food blogger wrote about it. The ____ brought hundreds of new customers the following week.","answer":"publicity"},{"passageId":"u8_25_publicity_passage_2","contextId":"u8_25_publicity_gap_2","text":"Before the new film came out, the actors appeared on chat shows and posted videos online. The studio spent millions on ____ to make sure everyone knew about it.","answer":"publicity"}],"contextDependentParaphrases":[],"wrongParaphrases":["private advice","public transport","secret plans"],"misleadingDistractors":["money that a company earns","a private meeting between managers","a written agreement between companies"],"teacherNote":"Noun: attention from newspapers, television and the internet, or work done to get that attention (good publicity, a publicity campaign). Boundary: publicity is attention from the public and the media; advertising is paid messages. The adjective public and the verb publicise are taught in the Word Family pathway."}]'::jsonb,'["public","publicise"]'::jsonb,'["bad publicity","a publicity campaign","attract publicity"]'::jsonb,'live'),
('vocab_qualified','qualified','adjective','having passed the exams or training needed to do a particular job','[{"senseId":"qualified_1","meaning":"having passed the exams or training needed to do a particular job","acceptedParaphrases":["trained and certified","officially trained for a job"],"masteryContexts":[{"contextId":"u8_26_qualified_meaning","text":"Ella is a qualified engineer, so she can sign the safety certificate for the bridge.","meaning":"having the official training for a job","wrongMeanings":["interested in a job but untrained","working in a job for no pay","new to a job and still learning"]},{"contextId":"u8_26_qualified_paraphrase","text":"After three years of training, Sam is now qualified to teach swimming.","meaning":"officially able to do a job because of training","wrongMeanings":["too young to do a job","paid well to do a job","afraid of doing a job"]}],"situationDistractors":["A boy who had never had a lesson tried to fix a car engine.","A volunteer with no training helped carry boxes at a charity shop.","A student read about first aid online for the first time.","A new worker was still learning how to use the till.","A child pretended to be a doctor in a game.","A man watched a video about plumbing but had never tried it."],"gapDistractors":[{"contextId":"u8_26_qualified_gap_1","answer":"qualified","wrong":["curved","concerned","launched"]},{"contextId":"u8_26_qualified_gap_2","answer":"qualified","wrong":["curved","launched","detailed"]},{"contextId":"u8_26_qualified_gap_3","answer":"qualified","wrong":["curved","launched","presented"]}],"spellingErrors":["qualifyed","qualifed","quallified","qualefied","quaified","kwalified"],"wordFamilyForms":[{"form":"qualified","partOfSpeech":"adjective","example":"The company only employs qualified electricians.","pedagogicallyUseful":true},{"form":"qualify","partOfSpeech":"verb","example":"Doctors train for many years before they qualify.","pedagogicallyUseful":true,"altExample":"Most students qualify as nurses after three years."},{"form":"unqualified","partOfSpeech":"adjective","example":"The report said that some unqualified workers had been doing dangerous jobs.","pedagogicallyUseful":true,"altExample":"Parents complained that an unqualified coach was teaching the swimming class."}],"masteryPassages":[{"passageId":"u8_26_qualified_passage_1","contextId":"u8_26_qualified_gap_1","text":"Mehmet finished his nursing course and passed all his exams last month. He is now a ____ nurse and has started work at the city hospital.","answer":"qualified"},{"passageId":"u8_26_qualified_passage_2","contextId":"u8_26_qualified_gap_2","text":"Do not let just anyone touch the gas boiler. Only an engineer who is ____ and holds the right certificate can repair it safely.","answer":"qualified"}],"contextDependentParaphrases":[],"wrongParaphrases":["keen but untrained","old and retired","new and unpaid"],"misleadingDistractors":["interested in a job but not yet trained","very experienced but without exams","paid more than other workers"],"teacherNote":"Adjective: having passed the exams or training needed for a job (a qualified teacher, qualified to do something). Boundary: qualified is about official training; experienced is about time spent doing the job. The verb qualify and the adjective unqualified are taught in the Word Family pathway; qualification is not repeated because it is a Unit 5 and Unit 7 target."}]'::jsonb,'["qualify","unqualified"]'::jsonb,'["a qualified teacher","highly qualified","qualified to do something"]'::jsonb,'live'),
('vocab_regulations','regulations','noun','official rules made by a government or organisation that people must obey','[{"senseId":"regulations_1","meaning":"official rules made by a government or organisation that people must obey","acceptedParaphrases":["official rules","rules set by authorities"],"masteryContexts":[{"contextId":"u8_27_regulations_meaning","text":"The factory was fined because it broke safety regulations.","meaning":"official rules that must be followed","wrongMeanings":["advice that may be ignored","machines that must be checked","reports that must be written"]},{"contextId":"u8_27_regulations_paraphrase","text":"Under the new regulations, restaurants must show how many calories are in each dish.","meaning":"official rules made by the government","wrongMeanings":["ideas suggested by customers","prices agreed by companies","menus written by chefs"]}],"situationDistractors":["A friend suggested trying a new café for lunch.","A manager thanked her team for their hard work.","A worker chose to wear a blue shirt on Friday.","A colleague recommended a good book about leadership.","A trainee asked where the toilets were.","A customer gave the waiter a tip."],"gapDistractors":[{"contextId":"u8_27_regulations_gap_1","answer":"regulations","wrong":["ingredients","facilities","structures"]},{"contextId":"u8_27_regulations_gap_2","answer":"regulations","wrong":["inspectors","elements","structures"]},{"contextId":"u8_27_regulations_gap_3","answer":"regulations","wrong":["ingredients","facilities","elements"]}],"spellingErrors":["regulasions","regualtions","regulatons","reguletions","regullations","regulatiions"],"wordFamilyForms":[{"form":"regulations","partOfSpeech":"noun","example":"All staff must follow the safety regulations.","pedagogicallyUseful":true},{"form":"regulate","partOfSpeech":"verb","example":"The government wants to regulate the use of drones.","pedagogicallyUseful":true,"altExample":"Laws regulate how much sugar can be added to baby food."},{"form":"regulator","partOfSpeech":"noun","example":"The energy regulator fined the company for overcharging customers.","pedagogicallyUseful":true,"altExample":"The regulator ordered the bank to pay back its customers."}],"masteryPassages":[{"passageId":"u8_27_regulations_passage_1","contextId":"u8_27_regulations_gap_1","text":"The government is worried about accidents on building sites. Under the new ____, every worker must wear a helmet and have safety training.","answer":"regulations"},{"passageId":"u8_27_regulations_passage_2","contextId":"u8_27_regulations_gap_2","text":"The restaurant was closed for a week. Inspectors found that it had broken several hygiene ____, including keeping raw meat next to cooked food.","answer":"regulations"}],"contextDependentParaphrases":[],"wrongParaphrases":["friendly suggestions","private opinions","personal habits"],"misleadingDistractors":["suggestions that people can ignore","reports written about a business","prizes given for good work"],"teacherNote":"Plural noun: official rules made by a government or organisation (safety regulations, follow the regulations). Boundary: regulations are official and must be obeyed; guidelines are advice. The verb regulate and the noun regulator are taught in the Word Family pathway."}]'::jsonb,'["regulate","regulator"]'::jsonb,'["safety regulations","strict regulations","follow the regulations"]'::jsonb,'live'),
('vocab_relentless','relentless','adjective','continuing in a strong way without stopping or becoming weaker','[{"senseId":"relentless_1","meaning":"continuing in a strong way without stopping or becoming weaker","acceptedParaphrases":["never stopping","continuing without a break"],"masteryContexts":[{"contextId":"u8_28_relentless_meaning","text":"The relentless noise from the building site made it impossible to concentrate.","meaning":"going on without any pause","wrongMeanings":["happening only now and then","starting suddenly and ending fast","quiet enough to ignore"]},{"contextId":"u8_28_relentless_paraphrase","text":"Her relentless hard work over ten years made the small business a success.","meaning":"continuing strongly without giving up","wrongMeanings":["done for a short time only","done without much care","done only when she felt like it"]}],"situationDistractors":["It rained for five minutes and then the sun came out.","A worker took a long break after every small task.","The phone rang once in the afternoon and then stayed silent.","The team worked hard on Monday but rested for the rest of the week.","A light breeze blew for a moment and stopped.","A manager checked her emails twice a week."],"gapDistractors":[{"contextId":"u8_28_relentless_gap_1","answer":"relentless","wrong":["creative","traditional","qualified"]},{"contextId":"u8_28_relentless_gap_2","answer":"relentless","wrong":["creative","sustainable","detailed"]},{"contextId":"u8_28_relentless_gap_3","answer":"relentless","wrong":["creative","traditional","sustainable"]}],"spellingErrors":["relentles","relentlas","releentless","relentliss","relenttless","relentlless"],"masteryPassages":[{"passageId":"u8_28_relentless_passage_1","contextId":"u8_28_relentless_gap_1","text":"The storm lasted for three days. The wind and rain were ____, and the workers could not go back to the building site until it finally stopped.","answer":"relentless"},{"passageId":"u8_28_relentless_passage_2","contextId":"u8_28_relentless_gap_2","text":"Before the opening of the new hotel, the staff worked fourteen hours a day for a month. The pressure was ____, and several people became ill.","answer":"relentless"}],"contextDependentParaphrases":[],"wrongParaphrases":["rarely happening","quickly ending","gently starting"],"misleadingDistractors":["happening only once in a while","gentle and easy to manage","stopping as soon as it begins"],"teacherNote":"Adjective: continuing strongly without stopping or becoming weaker (relentless pressure, relentless rain, a relentless effort). Boundary: relentless can describe something unpleasant (relentless noise) or a person’s determination (a relentless worker). The adverb relentlessly is the only other common form, so no family is taught."}]'::jsonb,'[]'::jsonb,'["relentless pressure","relentless rain","a relentless effort"]'::jsonb,'live'),
('vocab_response','response','noun','an answer or reaction to something that has been said or done','[{"senseId":"response_1","meaning":"an answer or reaction to something that has been said or done","acceptedParaphrases":["reaction","reply"],"masteryContexts":[{"contextId":"u8_29_response_meaning","text":"The manager’s response to the complaint was quick and polite.","meaning":"the reaction to something","wrongMeanings":["the reason for something","the cost of something","the start of something"]},{"contextId":"u8_29_response_paraphrase","text":"The new product got a very positive response from customers.","meaning":"reaction from people","wrongMeanings":["complaint from people","question from people","payment from people"]}],"situationDistractors":["A manager sent an email and is still waiting to hear back.","A worker asked a question that nobody has answered yet.","A shop put up a sign, but nobody has reacted to it.","A company sent out a survey that nobody has filled in.","A candidate posted a letter this morning.","A director started a meeting by asking a question."],"gapDistractors":[{"contextId":"u8_29_response_gap_1","answer":"response","wrong":["source","feature","minority"]},{"contextId":"u8_29_response_gap_2","answer":"response","wrong":["source","feature","landscape"]},{"contextId":"u8_29_response_gap_3","answer":"response","wrong":["source","feature","technology"]}],"spellingErrors":["responce","responese","reponse","risponse","respons","resopnse"],"wordFamilyForms":[{"form":"response","partOfSpeech":"noun","example":"The manager gave a quick response to the customer’s email.","pedagogicallyUseful":true},{"form":"respond","partOfSpeech":"verb","example":"Please respond to the invitation by Friday.","pedagogicallyUseful":true,"altExample":"The fire service can respond to an emergency in eight minutes."},{"form":"responsive","partOfSpeech":"adjective","example":"The company is very responsive to customer complaints.","pedagogicallyUseful":true,"altExample":"Customers like the new app because it is fast and responsive."}],"masteryPassages":[{"passageId":"u8_29_response_passage_1","contextId":"u8_29_response_gap_1","text":"Tom emailed three companies about work experience. He received a ____ from only one of them, but it offered him a place for two weeks.","answer":"response"},{"passageId":"u8_29_response_passage_2","contextId":"u8_29_response_gap_2","text":"The company asked customers what they thought of its new menu. The ____ was very positive, so the new dishes will stay.","answer":"response"}],"contextDependentParaphrases":[],"wrongParaphrases":["question","reason","request"],"misleadingDistractors":["a question asked at the start","a reason for doing something","a rule that must be followed"],"teacherNote":"Noun: an answer or reaction (a response to an email, a positive response, in response to). Boundary: a response follows something that has already happened or been said; it is not the first question. The verb respond and the adjective responsive are taught in the Word Family pathway."}]'::jsonb,'["respond","responsive"]'::jsonb,'["a positive response","in response to","receive a response"]'::jsonb,'live'),
('vocab_responsible_8','responsible','adjective','having the job or duty of dealing with something or someone at work','[{"senseId":"responsible_8_1","meaning":"having the job or duty of dealing with something or someone at work","acceptedParaphrases":["in charge","having the duty"],"masteryContexts":[{"contextId":"u8_30_responsible_8_meaning","text":"As head chef, Rosa is responsible for planning the menu and training the kitchen staff.","meaning":"having the duty of doing something as part of a job","wrongMeanings":["having no interest in doing something","being afraid of doing something","being too busy to do something"]},{"contextId":"u8_30_responsible_8_paraphrase","text":"The marketing team is responsible for all publicity about the new product.","meaning":"in charge of a task","wrongMeanings":["unaware of a task","unhappy about a task","excluded from a task"]}],"situationDistractors":["A visitor waited in the reception area to meet a friend.","A customer looked at the menu in a café window.","A passer-by watched builders working on a new wall.","A tourist took a photo of a factory.","A child watched the ducks in the park.","A shopper read the label on a jar of jam."],"gapDistractors":[{"contextId":"u8_30_responsible_8_gap_1","answer":"responsible","wrong":["traditional","creative","sustainable"]},{"contextId":"u8_30_responsible_8_gap_2","answer":"responsible","wrong":["traditional","creative","relentless"]},{"contextId":"u8_30_responsible_8_gap_3","answer":"responsible","wrong":["sustainable","traditional","relentless"]}],"spellingErrors":["responsable","resposible","responsibel","responcible","resonsible","responcable"],"wordFamilyForms":[{"form":"responsible","partOfSpeech":"adjective","example":"Pilots are responsible for the safety of their passengers.","pedagogicallyUseful":true},{"form":"responsibility","partOfSpeech":"noun","example":"Checking the stock is the responsibility of the night staff.","pedagogicallyUseful":true,"altExample":"Taking care of the plants is the responsibility of the cleaner."},{"form":"responsibly","partOfSpeech":"adverb","example":"Employees are expected to use company phones responsibly.","pedagogicallyUseful":true,"altExample":"Young workers should be taught to spend their wages responsibly."}],"masteryPassages":[{"passageId":"u8_30_responsible_8_passage_1","contextId":"u8_30_responsible_8_gap_1","text":"In the hotel, Ms Kahn deals with every complaint and organises the cleaning staff. She is ____ for making sure that guests are happy.","answer":"responsible"},{"passageId":"u8_30_responsible_8_passage_2","contextId":"u8_30_responsible_8_gap_2","text":"If a machine breaks, the engineers must fix it quickly. They are ____ for keeping the production line running all night.","answer":"responsible"}],"contextDependentParaphrases":[],"wrongParaphrases":["out of work","on holiday","off duty"],"misleadingDistractors":["not allowed to take part in something","unhappy about a decision","unaware of what is happening"],"teacherNote":"Adjective: having the job or duty of dealing with something at work (responsible for staff, responsible for safety). Unit 8 focuses on job duties (\"responsible for\"); Unit 7 taught the wider sense of being trustworthy. The noun responsibility and the adverb responsibly are taught in the Word Family pathway."}]'::jsonb,'["responsibility","responsibly"]'::jsonb,'["responsible for","be held responsible","directly responsible"]'::jsonb,'live')
